    self.sharedQueryTimer = C_Timer.NewTimer(SHARED_QUERY_RETRY_DELAY, --[[APR_DIAG]]APRTrace("APR-Core/core/VersionCheck.lua:213:callback#16", --[[/APR_DIAG]]function()
        self.sharedQueryTimer = nil
        self:SendSharedMessage("Q")
