end--[[APR_DIAG]]; APR.versionCheck.RefreshSharedChannel = APRTrace("APR-Core/core/VersionCheck.lua:199:APR.versionCheck:RefreshSharedChannel#15", APR.versionCheck.RefreshSharedChannel)--[[/APR_DIAG]]

